import type {
  HttpMethod,
  OperationContract,
  SecurityScheme,
} from "@/lib/api/contracts/registry";
import { errorEnvelopeSchema } from "@/lib/api/contracts/shared";

import { toJsonSchema, schemaProperties, type JsonSchema } from "./zod-schema";

/**
 * Build a deterministic OpenAPI 3.1 document from the contract registry
 * (Phase C1, SKILL §2.5). The output is committed as `openapi.yaml` and
 * regenerated by `npm run openapi:generate`; CI fails if the committed file
 * drifts from the code.
 */

const METHOD_ORDER: Record<HttpMethod, number> = {
  GET: 0,
  POST: 1,
  PUT: 2,
  PATCH: 3,
  DELETE: 4,
};

/** Locale-independent ordering so the committed spec is byte-stable in CI. */
function compareStrings(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

const SECURITY_REQUIREMENTS: Record<SecurityScheme, unknown[]> = {
  session: [{ sessionCookie: [] }],
  cron: [{ cronSecret: [] }],
  webhook: [{ googleOidc: [] }],
  public: [],
};

const ERROR_RESPONSES: Record<number, { description: string }> = {
  400: { description: "Syntactic validation failure (invalid body/query)." },
  401: { description: "Missing or invalid credentials." },
  403: { description: "Authenticated but not permitted." },
  404: { description: "Resource not found." },
  409: { description: "State conflict (duplicate/unique violation)." },
  422: { description: "Semantic validation failure (domain rule)." },
  429: { description: "Rate limit exceeded; see `Retry-After`." },
  500: { description: "Unhandled server error (redacted)." },
  503: { description: "Feature disabled or dependency unavailable." },
};

/** Error responses added to every operation that does not declare them. */
function defaultErrorStatuses(security: SecurityScheme): number[] {
  switch (security) {
    case "session":
      return [400, 401, 403, 404, 409, 422, 429, 500];
    case "cron":
      return [401, 500, 503];
    case "webhook":
      return [400, 401, 500, 503];
    default:
      return [500, 503];
  }
}

const ERROR_SCHEMA = toJsonSchema(errorEnvelopeSchema, "output");

export type OpenApiTag = { name: string; description?: string };

export type BuildDocumentOptions = {
  version: string;
  title?: string;
  description?: string;
  servers?: { url: string; description?: string }[];
  tags?: OpenApiTag[];
};

type ParameterObject = {
  name: string;
  in: "path" | "query";
  required: boolean;
  schema: JsonSchema;
};

function buildParameters(operation: OperationContract): ParameterObject[] {
  const parameters: ParameterObject[] = [];

  if (operation.params) {
    const { properties } = schemaProperties(operation.params);
    for (const [name, schema] of Object.entries(properties)) {
      parameters.push({
        name,
        in: "path",
        // OpenAPI requires path params to be `required: true` regardless of the
        // schema's optionality.
        required: true,
        schema,
      });
    }
  }

  if (operation.query) {
    const { properties, required } = schemaProperties(operation.query);
    for (const [name, schema] of Object.entries(properties)) {
      parameters.push({
        name,
        in: "query",
        required: required.includes(name),
        schema,
      });
    }
  }

  return parameters.sort((a, b) =>
    a.in === b.in ? compareStrings(a.name, b.name) : compareStrings(a.in, b.in),
  );
}

/** Build an OpenAPI operation object from one contract. */
function buildOperation(operation: OperationContract) {
  const responses: Record<string, unknown> = {};

  const statuses = Object.keys(operation.responses)
    .map((value) => Number(value))
    .sort((a, b) => a - b);
  for (const status of statuses) {
    const spec = operation.responses[status]!;
    const contentType = spec.contentType ?? "application/json";
    const content =
      spec.schema !== undefined
        ? { [contentType]: { schema: toJsonSchema(spec.schema, "output") } }
        : spec.contentType !== undefined
          ? { [contentType]: {} }
          : undefined;
    responses[String(status)] = {
      description: spec.description,
      ...(content ? { content } : {}),
    };
  }

  for (const status of defaultErrorStatuses(operation.security)) {
    const key = String(status);
    if (responses[key]) continue;
    const meta = ERROR_RESPONSES[status] ?? { description: "Error" };
    responses[key] = {
      description: meta.description,
      content: {
        "application/json": {
          schema: { $ref: "#/components/schemas/ErrorEnvelope" },
        },
      },
    };
  }

  const parameters = buildParameters(operation);

  return {
    operationId: operation.operationId,
    tags: [...operation.tags].sort(),
    summary: operation.summary,
    ...(operation.description ? { description: operation.description } : {}),
    ...(operation.deprecated ? { deprecated: true } : {}),
    ...(parameters.length > 0 ? { parameters } : {}),
    ...(operation.body
      ? {
          requestBody: {
            required: true,
            content: {
              "application/json": {
                schema: toJsonSchema(operation.body, "input"),
              },
            },
          },
        }
      : {}),
    responses,
    security: SECURITY_REQUIREMENTS[operation.security],
  };
}

export type OpenApiDocument = ReturnType<typeof buildOpenApiDocument>;

export function buildOpenApiDocument(
  operations: readonly OperationContract[],
  options: BuildDocumentOptions,
) {
  const paths: Record<string, Record<string, unknown>> = {};

  const sorted = [...operations].sort((a, b) => {
    if (a.path !== b.path) return compareStrings(a.path, b.path);
    return METHOD_ORDER[a.method] - METHOD_ORDER[b.method];
  });

  for (const operation of sorted) {
    paths[operation.path] ??= {};
    paths[operation.path]![operation.method.toLowerCase()] =
      buildOperation(operation);
  }

  const tagNames = new Set(operations.flatMap((operation) => operation.tags));
  const declaredTags = options.tags ?? [];
  const declaredByName = new Map(declaredTags.map((tag) => [tag.name, tag]));
  const tags = [...tagNames]
    .sort()
    .map((name) => declaredByName.get(name) ?? { name });

  return {
    openapi: "3.1.0",
    info: {
      title: options.title ?? "Lunabox API",
      version: options.version,
      ...(options.description ? { description: options.description } : {}),
    },
    ...(options.servers ? { servers: options.servers } : {}),
    tags,
    paths,
    components: {
      schemas: {
        ErrorEnvelope: ERROR_SCHEMA,
      },
      securitySchemes: {
        sessionCookie: {
          type: "apiKey",
          in: "cookie",
          name: "better-auth.session_token",
          description:
            "Better Auth session cookie set at sign-in. Server-side sessions.",
        },
        cronSecret: {
          type: "http",
          scheme: "bearer",
          description:
            "Vercel cron: `Authorization: Bearer $CRON_SECRET` (constant-time compared).",
        },
        googleOidc: {
          type: "http",
          scheme: "bearer",
          bearerFormat: "JWT",
          description: "Google Pub/Sub push OIDC token, verified asymmetrically.",
        },
      },
    },
  };
}
